static char *A[2035];
static char gbuf[256];

static void bad(int i, const char *what) { printf("unexpected %s at op %d\n", what, i); }

static int allis(const char *p, size_t n, unsigned char v)
{
    for (size_t i = 0; i < n; i++)
        if ((unsigned char)p[i] != v) return 0;
    return 1;
}

int main(void)
{
    char stk[64];
    memset(stk, 0, sizeof stk);
    for (int i = 0; i < (int)(sizeof ops / sizeof ops[0]); i++) {
        const op_t *o = &ops[i];
        switch (o->op) {
        case OM: case ORM:
            A[o->a] = o->op == OM ? my_malloc((size_t)o->c) : my_realloc(NULL, (size_t)o->c);
            if (!A[o->a]) { bad(i, "NULL"); break; }
            memset(A[o->a], (int)o->d, (size_t)o->c);
            break;
        case OMN:
            if (my_malloc((size_t)o->c)) bad(i, "non-NULL");
            break;
        case OC:
            A[o->a] = my_calloc((size_t)o->c, (size_t)o->d);
            if (!A[o->a]) { bad(i, "NULL"); break; }
            if (!allis(A[o->a], (size_t)(o->c * o->d), 0)) bad(i, "nonzero calloc");
            memset(A[o->a], (int)o->e, (size_t)(o->c * o->d));
            break;
        case OCN:
            if (my_calloc((size_t)o->c, (size_t)o->d)) bad(i, "non-NULL");
            break;
        case OF: my_free(A[o->a] + o->c); break;
        case OFN: my_free(NULL); break;
        case OFS: my_free(stk + o->c); break;
        case OFG: my_free(gbuf + o->c); break;
        case ORV: {
            char *old = A[o->a];
            char *p = my_realloc(old, (size_t)o->c);
            if (!p) { bad(i, "NULL"); break; }
            A[o->b] = p;
            if ((p == old) != (int)((o->e >> 16) & 1)) bad(i, "placement");
            if (!allis(p, (size_t)o->d, (unsigned char)(o->e & 0xff))) bad(i, "data lost");
            memset(p, (int)((o->e >> 8) & 0xff), (size_t)o->c);
            break;
        }
        case ORN:
            if (my_realloc(A[o->a] + o->c, (size_t)o->d)) bad(i, "non-NULL");
            break;
        case ORS:
            if (my_realloc(o->e ? gbuf + o->c : stk + o->c, (size_t)o->d)) bad(i, "non-NULL");
            break;
        case OW: ((unsigned char *)A[o->a])[o->c] = (unsigned char)o->d; break;
        case ORD:
            if (((unsigned char *)A[o->a])[o->c] != (unsigned char)o->d) bad(i, "byte value");
            break;
        case ODL: my_set_delay((int)o->c); break;
        case OPL: my_set_policy((int)o->c); break;
        case ODP: my_heap_dump(); break;
        case OLK: my_leak_report(); break;
        case OSAY: printf("-- %lld\n", o->c); break;
        }
    }
    return 0;
}
